#!/bin/sh
#
# LogiCoy eRx — self-extracting installer for OpenEMR.
#
# This file carries the whole module inside it. Copy it to the OpenEMR server,
# run it, and it places the module under
# interface/modules/custom_modules/oe-module-logicoy-erx with the ownership and
# permissions the web server needs.
#
# It does NOT register the module — that is a deliberate admin action in
# Modules -> Manage Modules. The steps are printed when the copy finishes, and
# are also in docs/INSTALL.md inside the installed module.
#
# Generated by scripts/build_installer.sh — do not edit this file by hand.
#
# license  https://github.com/openemr/openemr/blob/master/LICENSE GNU General Public License 3

set -eu

MODULE_NAME="oe-module-logicoy-erx"
MODULE_VERSION="@@MODULE_VERSION@@"
PAYLOAD_SHA256="@@PAYLOAD_SHA256@@"
MIN_OPENEMR="7.0.0"
MIN_PHP="8.1"

OPENEMR_ROOT=""
ROOT_GIVEN=0
CONTAINER=""
WEB_USER=""
SITE="default"
DO_BACKUP=1
BACKUP_DIR=""
DRY_RUN=0
CREATE_TABLES=0
EXTRACT_ONLY=""
ASSUME_YES=0

# ---------------------------------------------------------------- output ----

say()  { printf '%s\n' "$*"; }
step() { printf '\n==> %s\n' "$*"; }
warn() { printf 'warning: %s\n' "$*" >&2; }
die()  { printf 'error: %s\n' "$*" >&2; exit 1; }

usage() {
    cat <<TXT
LogiCoy eRx installer ${MODULE_VERSION}

  sh $0 [options]

Options:
  --openemr-root=PATH   OpenEMR installation directory. Auto-detected when
                        omitted (the directory containing interface/globals.php).
  --container=NAME      Install into this Docker container instead of the local
                        filesystem. The installer copies itself in and runs
                        there. Offered automatically when OpenEMR is not on this
                        machine but a container is running it.
  --user=NAME           Web server user that must own the files. Auto-detected
                        from the owner of the existing OpenEMR files.
  --site=NAME           OpenEMR site, used only with --create-tables (default: default).
  --create-tables       Also create the module's database tables now, instead of
                        letting the Install button in Manage Modules do it.
                        Must run as root or as the web server user.
  --no-backup           Do not archive an existing installed module first.
  --backup-dir=PATH     Where to write that archive (default: the current
                        directory). Never inside the OpenEMR module tree —
                        OpenEMR scans that directory and would list the backup
                        as a second, broken module.
  --extract-only=DIR    Unpack the module into DIR and stop. Nothing is installed.
  --dry-run             Report what would happen; change nothing.
  --yes                 Do not prompt before replacing an existing installation.
  --version             Print the module version and exit.
  --help                This message.

Docker: the module has to land on the container's filesystem, not the host's.
        Run this on the host with --container=NAME and it will do that for you,
        or run it inside the container yourself.

        A module installed into a container lives in its writable layer and is
        lost on the next image update. Reinstall it after an update, or
        bind-mount the module directory.
TXT
}

# ------------------------------------------------------------- arguments ----

for arg in "$@"; do
    case "$arg" in
        --openemr-root=*) OPENEMR_ROOT="${arg#*=}"; ROOT_GIVEN=1 ;;
        --container=*)    CONTAINER="${arg#*=}" ;;
        --user=*)         WEB_USER="${arg#*=}" ;;
        --site=*)         SITE="${arg#*=}" ;;
        --create-tables)  CREATE_TABLES=1 ;;
        --no-backup)      DO_BACKUP=0 ;;
        --backup-dir=*)   BACKUP_DIR="${arg#*=}" ;;
        --extract-only=*) EXTRACT_ONLY="${arg#*=}" ;;
        --dry-run)        DRY_RUN=1 ;;
        --yes|-y)         ASSUME_YES=1 ;;
        --version)        say "$MODULE_NAME $MODULE_VERSION"; exit 0 ;;
        --help|-h)        usage; exit 0 ;;
        *)                usage >&2; die "unknown option: $arg" ;;
    esac
done

# --------------------------------------------------------------- payload ----

# The archive is appended to this script after the __PAYLOAD_BELOW__ marker, so
# the script has to be able to read itself. That rules out `curl ... | sh`.
case "$0" in
    -*|"") die "run this installer as a file (sh ./$MODULE_NAME-installer.sh), not from a pipe" ;;
esac
[ -f "$0" ] || die "cannot read $0 — copy the installer to disk and run it from there"

decode_base64() {
    if base64 --decode </dev/null >/dev/null 2>&1; then
        base64 --decode
    elif base64 -d </dev/null >/dev/null 2>&1; then
        base64 -d
    elif base64 -D </dev/null >/dev/null 2>&1; then
        base64 -D
    elif command -v openssl >/dev/null 2>&1; then
        openssl enc -d -base64 -A
    else
        die "no base64 decoder found (need base64 or openssl)"
    fi
}

extract_payload() {
    # +1 skips the marker line itself.
    marker=$(grep -n '^__PAYLOAD_BELOW__$' "$0" | head -1 | cut -d: -f1)
    [ -n "$marker" ] || die "payload marker missing — this installer is truncated"
    tail -n "+$((marker + 1))" "$0" | decode_base64 > "$1"
}

verify_payload() {
    archive="$1"
    actual=""
    if command -v sha256sum >/dev/null 2>&1; then
        actual=$(sha256sum "$archive" | cut -d' ' -f1)
    elif command -v shasum >/dev/null 2>&1; then
        actual=$(shasum -a 256 "$archive" | cut -d' ' -f1)
    elif command -v openssl >/dev/null 2>&1; then
        actual=$(openssl dgst -sha256 "$archive" | sed 's/.*= *//')
    else
        warn "no sha256 tool available — skipping integrity check"
        return 0
    fi
    [ "$actual" = "$PAYLOAD_SHA256" ] || die "payload checksum mismatch — the installer was altered or damaged in transit
  expected $PAYLOAD_SHA256
  got      $actual"
    say "checksum ok ($PAYLOAD_SHA256)"
}

# ----------------------------------------------------------------- setup ----

TMPDIR_WORK=$(mktemp -d "${TMPDIR:-/tmp}/logicoy-erx.XXXXXX") || die "cannot create a temporary directory"
# Separate from TMPDIR_WORK, which the exit trap removes — a backup that is
# deleted on the way out is not a backup.
TMPDIR_WORK_KEEP="${TMPDIR:-/tmp}/logicoy-erx-backups"
cleanup() { rm -rf "$TMPDIR_WORK"; }
trap cleanup EXIT INT TERM

say "LogiCoy eRx $MODULE_VERSION installer"

step "Unpacking"
ARCHIVE="$TMPDIR_WORK/module.tar.gz"
extract_payload "$ARCHIVE"
verify_payload "$ARCHIVE"

command -v tar >/dev/null 2>&1 || die "tar is required and was not found"
mkdir -p "$TMPDIR_WORK/unpacked"
tar -xzf "$ARCHIVE" -C "$TMPDIR_WORK/unpacked" || die "the archive could not be unpacked"
SRC="$TMPDIR_WORK/unpacked/$MODULE_NAME"
[ -f "$SRC/openemr.bootstrap.php" ] || die "the archive does not contain a complete module"
say "unpacked $(find "$SRC" -type f | wc -l | tr -d ' ') files"

# --extract-only exists so a site that deploys through configuration management
# can take the files without this script touching the OpenEMR tree.
if [ -n "$EXTRACT_ONLY" ]; then
    step "Extracting only"
    if [ "$DRY_RUN" -eq 1 ]; then
        say "would write $EXTRACT_ONLY/$MODULE_NAME"
        exit 0
    fi
    mkdir -p "$EXTRACT_ONLY"
    [ -e "$EXTRACT_ONLY/$MODULE_NAME" ] && die "$EXTRACT_ONLY/$MODULE_NAME already exists"
    cp -R "$SRC" "$EXTRACT_ONLY/$MODULE_NAME"
    say "wrote $EXTRACT_ONLY/$MODULE_NAME"
    exit 0
fi

# ---------------------------------------------------------------- docker ----

# OpenEMR is very often run from a container, and the installer is very often
# copied to the host and run there — where there is no OpenEMR to install into.
# Rather than dead-ending on that, find the container and install into it.

CONTAINER_OPENEMR="/var/www/localhost/htdocs/openemr"

docker_available() {
    command -v docker >/dev/null 2>&1 && docker info >/dev/null 2>&1
}

# Names of running containers that look like they hold an OpenEMR installation.
find_openemr_containers() {
    running=$(docker ps --format '{{.Names}}' 2>/dev/null || true)
    [ -n "$running" ] || return 0

    # Name or image first: cheap, and right almost every time.
    matched=$(docker ps --format '{{.Names}}\t{{.Image}}' 2>/dev/null \
        | grep -i 'openemr' | cut -f1 || true)
    if [ -n "$matched" ]; then
        printf '%s\n' "$matched"
        return 0
    fi

    # Otherwise look inside. Only reached when nothing is named for OpenEMR, so
    # the cost of a probe per container is paid rarely.
    for name in $running; do
        if docker exec "$name" test -f "$CONTAINER_OPENEMR/interface/globals.php" >/dev/null 2>&1; then
            printf '%s\n' "$name"
        fi
    done
}

# Re-runs this same installer inside a container. Everything the caller asked
# for is forwarded, except --openemr-root when it was never given: a host path
# means nothing in there.
install_into_container() {
    target_container="$1"

    docker inspect "$target_container" >/dev/null 2>&1 \
        || die "no such container: $target_container"
    [ "$(docker inspect -f '{{.State.Running}}' "$target_container" 2>/dev/null)" = "true" ] \
        || die "container $target_container is not running"

    fwd=""
    [ "$ROOT_GIVEN" -eq 1 ] && fwd="$fwd --openemr-root='$OPENEMR_ROOT'"
    [ -n "$WEB_USER" ]      && fwd="$fwd --user='$WEB_USER'"
    [ "$SITE" != "default" ] && fwd="$fwd --site='$SITE'"
    [ "$CREATE_TABLES" -eq 1 ] && fwd="$fwd --create-tables"
    [ "$DRY_RUN" -eq 1 ]    && fwd="$fwd --dry-run"
    [ "$ASSUME_YES" -eq 1 ] && fwd="$fwd --yes"
    if [ "$DO_BACKUP" -eq 0 ]; then
        fwd="$fwd --no-backup"
    else
        # The container's working directory is not somewhere to drop a tarball,
        # and the caller's host path does not exist in there either.
        fwd="$fwd --backup-dir='${BACKUP_DIR:-/tmp}'"
    fi

    remote="/tmp/logicoy-erx-installer.$$.sh"
    say "copying the installer into $target_container"
    docker cp "$0" "$target_container:$remote" >/dev/null \
        || die "could not copy the installer into $target_container"

    tty_flag=""
    [ -t 0 ] && tty_flag="-t"

    status=0
    # shellcheck disable=SC2086
    docker exec -i $tty_flag "$target_container" sh -c "sh '$remote' $fwd" || status=$?
    docker exec "$target_container" rm -f "$remote" >/dev/null 2>&1 || true

    if [ "$status" -ne 0 ]; then
        die "the installer failed inside $target_container (exit $status)"
    fi

    step "Installed inside the container $target_container"
    cat <<TXT

  Everything above happened inside the container, including any backup archive.

  Unless the output above says the module directory is a bind mount, the module
  now lives in the container's writable layer and is gone after an image update
  or a "docker compose up --force-recreate" — the same trap as a key file on a
  path. Reinstall it after an update, or bind-mount the module directory in your
  compose file:

      volumes:
        - ./oe-module-logicoy-erx:$CONTAINER_OPENEMR/interface/modules/custom_modules/oe-module-logicoy-erx

TXT
    exit 0
}

if [ -n "$CONTAINER" ]; then
    step "Installing into a container"
    docker_available || die "docker is not available on this machine, so --container cannot be used"
    install_into_container "$CONTAINER"
fi

# Reported when there is no OpenEMR on this filesystem. Almost always a
# containerised install, so look for that before giving up.
no_openemr_here() {
    if ! docker_available; then
        die "could not find OpenEMR on this machine. Pass --openemr-root=/path/to/openemr

If OpenEMR runs in a container, run this installer inside that container, or on
a host where docker is usable, with --container=NAME."
    fi

    candidates=$(find_openemr_containers)
    count=$(printf '%s' "$candidates" | grep -c . || true)

    if [ "$count" -eq 0 ]; then
        die "could not find OpenEMR on this machine, and no running container appears
to hold one. Pass --openemr-root=/path/to/openemr, or --container=NAME if the
container is named something unexpected."
    fi

    if [ "$count" -gt 1 ]; then
        say "OpenEMR is not on this machine, but these containers look like they run it:"
        printf '%s\n' "$candidates" | sed 's/^/    /'
        die "pick one with --container=NAME"
    fi

    say "OpenEMR is not installed on this machine, but the container '$candidates'"
    say "looks like it runs it."
    if [ "$ASSUME_YES" -eq 0 ]; then
        if [ -t 0 ]; then
            printf 'Install into that container? [y/N] '
            read -r reply
            case "$reply" in
                y|Y|yes|YES) ;;
                *) die "aborted — re-run with --container=$candidates to install into it" ;;
            esac
        else
            die "re-run with --container=$candidates to install into it"
        fi
    fi

    install_into_container "$candidates"
}

# ------------------------------------------------------ locate the target ----

step "Locating OpenEMR"

if [ -z "$OPENEMR_ROOT" ]; then
    for candidate in \
        /var/www/localhost/htdocs/openemr \
        /var/www/html/openemr \
        /var/www/openemr \
        /var/www/html \
        /usr/share/openemr \
        "$PWD"
    do
        if [ -f "$candidate/interface/globals.php" ]; then
            OPENEMR_ROOT="$candidate"
            break
        fi
    done
fi

# Exits, either into a container or with an explanation.
[ -n "$OPENEMR_ROOT" ] || no_openemr_here
given_root="$OPENEMR_ROOT"
OPENEMR_ROOT=$(cd "$given_root" 2>/dev/null && pwd) || die "--openemr-root does not exist: $given_root"
[ -f "$OPENEMR_ROOT/interface/globals.php" ] \
    || die "$OPENEMR_ROOT does not look like an OpenEMR installation (no interface/globals.php)"

CUSTOM_MODULES="$OPENEMR_ROOT/interface/modules/custom_modules"
[ -d "$CUSTOM_MODULES" ] || die "$CUSTOM_MODULES is missing — is this a supported OpenEMR version?"

TARGET="$CUSTOM_MODULES/$MODULE_NAME"
say "OpenEMR:  $OPENEMR_ROOT"
say "Target:   $TARGET"

# ------------------------------------------------------------ preflight -----

step "Checking requirements"

# OpenEMR's own version.php carries a comment mentioning $v_patch a few lines
# below the assignment ("the above $v_patch variable is a misnomer"), so a
# pattern loose enough to match the variable anywhere reads that comment as the
# value and yields "8.3." instead of "8.3.0". Match assignments only, and accept
# the value quoted or bare.
read_php_version() {
    awk '
        function value(line) {
            sub(/^[^=]*=[ \t]*/, "", line)   # drop everything up to the "="
            sub(/;.*$/, "", line)            # drop the semicolon and any comment
            gsub(/[\047" \t\r]/, "", line)  # drop quotes and whitespace
            return line
        }
        /^[ \t]*\$v_major[ \t]*=/ { major = value($0) }
        /^[ \t]*\$v_minor[ \t]*=/ { minor = value($0) }
        /^[ \t]*\$v_patch[ \t]*=/ { patch = value($0) }
        END {
            if (major !~ /^[0-9]+$/) { exit 1 }
            if (minor !~ /^[0-9]+$/) { minor = 0 }
            if (patch !~ /^[0-9]+$/) { patch = 0 }
            print major "." minor "." patch
        }
    ' "$1"
}

version_lt() {
    # Returns 0 when $1 < $2, comparing dotted numeric versions.
    [ "$1" = "$2" ] && return 1
    smallest=$(printf '%s\n%s\n' "$1" "$2" | sort -t. -k1,1n -k2,2n -k3,3n | head -1)
    [ "$smallest" = "$1" ]
}

if [ -f "$OPENEMR_ROOT/version.php" ]; then
    OE_VERSION=$(read_php_version "$OPENEMR_ROOT/version.php" || true)
    if [ -n "$OE_VERSION" ]; then
        if version_lt "$OE_VERSION" "$MIN_OPENEMR"; then
            die "OpenEMR $OE_VERSION is older than the minimum supported $MIN_OPENEMR"
        fi
        say "OpenEMR version $OE_VERSION (minimum $MIN_OPENEMR) ok"
    else
        warn "could not read the OpenEMR version — continuing"
    fi
else
    warn "no version.php in $OPENEMR_ROOT — skipping the OpenEMR version check"
fi

if command -v php >/dev/null 2>&1; then
    PHP_VERSION=$(php -r 'echo PHP_MAJOR_VERSION . "." . PHP_MINOR_VERSION;' 2>/dev/null || true)
    if [ -n "$PHP_VERSION" ]; then
        if version_lt "$PHP_VERSION" "$MIN_PHP"; then
            die "PHP $PHP_VERSION is older than the minimum supported $MIN_PHP"
        fi
        say "PHP $PHP_VERSION (minimum $MIN_PHP) ok"
    fi
else
    # The CLI is only needed for the queue worker and the credential loader, so
    # its absence is worth reporting but is not fatal to placing the files.
    warn "no php on PATH — the queue worker and credential loader need the PHP CLI"
fi

# Ownership is taken from OpenEMR's own files rather than guessed from a list of
# distro defaults: whoever owns interface/globals.php is by definition the user
# the web server runs as here.
owner_of() {
    stat -c '%U' "$1" 2>/dev/null || stat -f '%Su' "$1" 2>/dev/null || true
}
group_of() {
    stat -c '%G' "$1" 2>/dev/null || stat -f '%Sg' "$1" 2>/dev/null || true
}

DETECTED_USER=$(owner_of "$OPENEMR_ROOT/interface/globals.php")
DETECTED_GROUP=$(group_of "$OPENEMR_ROOT/interface/globals.php")
[ -n "$WEB_USER" ] || WEB_USER="$DETECTED_USER"
WEB_GROUP="${DETECTED_GROUP:-$WEB_USER}"
if [ -n "$WEB_USER" ]; then
    say "Web server user: $WEB_USER:$WEB_GROUP"
else
    warn "could not determine the web server user — file ownership will be left alone"
fi

CURRENT_USER=$(id -un 2>/dev/null || echo unknown)
if [ "$(id -u 2>/dev/null || echo 1)" -ne 0 ] && [ -n "$WEB_USER" ] && [ "$CURRENT_USER" != "$WEB_USER" ]; then
    warn "running as '$CURRENT_USER'; ownership cannot be set to '$WEB_USER' without root"
fi

[ -w "$CUSTOM_MODULES" ] || die "$CUSTOM_MODULES is not writable by '$CURRENT_USER' — re-run with sudo"

# ------------------------------------------------------------- existing -----

REPLACING=0
OLD_VERSION=""

# Detected before anything else touches the target: whether the path is a mount
# decides how the files are placed, not just whether to ask first.
BIND_MOUNTED=0
if [ -e "$TARGET" ] && [ -r /proc/mounts ] \
   && awk -v t="$TARGET" '$2 == t { found = 1 } END { exit !found }' /proc/mounts; then
    BIND_MOUNTED=1
fi

# An empty directory is not an installation to replace — and the recommended way
# to make a containerised install survive an image update is to bind-mount an
# empty directory here, so this is the normal case on Docker, not an edge one.
TARGET_EMPTY=0
if [ -d "$TARGET" ] && [ -z "$(find "$TARGET" -mindepth 1 2>/dev/null | head -1)" ]; then
    TARGET_EMPTY=1
fi

if [ -e "$TARGET" ] && [ "$TARGET_EMPTY" -eq 0 ]; then
    REPLACING=1
    if [ -f "$TARGET/version.php" ]; then
        OLD_VERSION=$(read_php_version "$TARGET/version.php" || true)
    fi
    step "Existing installation"
    say "found ${OLD_VERSION:-an unknown version} at $TARGET"
    say "it will be replaced by $MODULE_VERSION"
    say "Module tables and credentials are untouched — only the files are replaced."

    if [ "$BIND_MOUNTED" -eq 1 ]; then
        warn "$TARGET is a bind mount"
        # Only reached with files present: an empty mount has nothing to lose and
        # never gets here.
        warn "its contents will be replaced, and the change is written through to the"
        warn "directory it is mounted from — outside this container. If that is a"
        warn "source checkout rather than a deployment directory, stop now."
        # Never overwrite a mount on an unattended run, whatever --yes says.
        ASSUME_YES=0
    fi
    if [ "$ASSUME_YES" -eq 0 ] && [ "$DRY_RUN" -eq 0 ]; then
        if [ -t 0 ]; then
            printf 'Continue? [y/N] '
            read -r reply
            case "$reply" in
                y|Y|yes|YES) ;;
                *) die "aborted" ;;
            esac
        elif [ "$BIND_MOUNTED" -eq 1 ]; then
            die "refusing to overwrite a bind-mounted directory on an unattended run.
--yes does not cover this: the files being replaced live outside this container.
If you really mean to replace them, run the installer from a terminal and answer
the prompt, or point it somewhere that is not a mount."
        else
            die "an installation already exists; re-run with --yes to replace it"
        fi
    fi
fi

# ------------------------------------------------------------- install ------

step "Installing"

if [ "$DRY_RUN" -eq 1 ]; then
    say "would install $MODULE_VERSION into $TARGET"
    [ "$REPLACING" -eq 1 ] && [ "$DO_BACKUP" -eq 1 ] && say "would archive the existing directory to ${BACKUP_DIR:-$PWD}"
    [ -n "$WEB_USER" ] && say "would chown -R $WEB_USER:$WEB_GROUP $TARGET"
    [ "$CREATE_TABLES" -eq 1 ] && say "would create the module tables for site '$SITE'"
    say "dry run — nothing was changed"
    exit 0
fi

if [ "$REPLACING" -eq 1 ]; then
    if [ "$DO_BACKUP" -eq 1 ]; then
        # Archived, and archived out of the module tree. A directory left
        # beside the module — even renamed .bak — is picked up by the Manage
        # Modules scan and offered as a second module to register.
        [ -n "$BACKUP_DIR" ] || BACKUP_DIR="$PWD"
        if ! mkdir -p "$BACKUP_DIR" 2>/dev/null || [ ! -w "$BACKUP_DIR" ]; then
            warn "$BACKUP_DIR is not writable — keeping the backup in $TMPDIR_WORK_KEEP instead"
            BACKUP_DIR="$TMPDIR_WORK_KEEP"
            mkdir -p "$BACKUP_DIR"
        fi
        BACKUP="$BACKUP_DIR/$MODULE_NAME-${OLD_VERSION:-previous}-$(date +%Y%m%d%H%M%S).tar.gz"
        if tar -czf "$BACKUP" -C "$CUSTOM_MODULES" "$MODULE_NAME" 2>/dev/null; then
            say "previous version archived to $BACKUP"
        else
            die "could not archive the existing installation to $BACKUP — re-run with --no-backup to replace it anyway"
        fi
    fi
fi

# Staged next to the target and then moved, so the module directory is never
# half-populated — OpenEMR scans that directory and a partial module registers
# as broken.
STAGE="$CUSTOM_MODULES/.$MODULE_NAME.installing.$$"
rm -rf "$STAGE"
cp -R "$SRC" "$STAGE"

find "$STAGE" -type d -exec chmod 755 {} + 2>/dev/null || true
find "$STAGE" -type f -exec chmod 644 {} + 2>/dev/null || true
for cli in scripts/queue_worker.php scripts/load_credential.php; do
    [ -f "$STAGE/$cli" ] && chmod 644 "$STAGE/$cli"
done

if [ -n "$WEB_USER" ]; then
    if chown -R "$WEB_USER:$WEB_GROUP" "$STAGE" 2>/dev/null; then
        say "owned by $WEB_USER:$WEB_GROUP"
    else
        warn "could not chown to $WEB_USER:$WEB_GROUP — set the ownership yourself:"
        warn "  chown -R $WEB_USER:$WEB_GROUP $TARGET"
    fi
fi

if [ "$BIND_MOUNTED" -eq 1 ]; then
    # A bind mount cannot be removed from inside the container ("Resource busy")
    # and must not be — the directory belongs to whoever mounted it. Empty it and
    # fill it instead. Everything written here goes through the mount to the
    # directory it comes from.
    find "$TARGET" -mindepth 1 -exec rm -rf {} + 2>/dev/null || true
    remaining=$(find "$TARGET" -mindepth 1 | head -1)
    [ -z "$remaining" ] || die "could not empty $TARGET — something in it is in use"

    cp -R "$STAGE/." "$TARGET/" || die "could not copy the module into $TARGET"
    rm -rf "$STAGE"

    # Reapplied here because cp does not carry ownership across.
    find "$TARGET" -type d -exec chmod 755 {} + 2>/dev/null || true
    find "$TARGET" -type f -exec chmod 644 {} + 2>/dev/null || true
    if [ -n "$WEB_USER" ]; then
        chown -R "$WEB_USER:$WEB_GROUP" "$TARGET" 2>/dev/null \
            || warn "could not chown $TARGET to $WEB_USER:$WEB_GROUP"
    fi

    say "installed $MODULE_VERSION into $TARGET"
    say "That path is a bind mount, so the files were written through to the"
    say "directory it is mounted from. They will survive a container rebuild."
else
    # Removed here rather than earlier so a failure while staging leaves the
    # previous installation untouched. mv onto an existing directory would nest
    # the new one inside it.
    rm -rf "$TARGET"
    mv "$STAGE" "$TARGET"
    say "installed $MODULE_VERSION into $TARGET"
fi

# --------------------------------------------------------- module tables ----

if [ "$CREATE_TABLES" -eq 1 ]; then
    step "Creating module tables"
    command -v php >/dev/null 2>&1 || die "--create-tables needs the PHP CLI, which is not on PATH"

    # sql/install.sql is guarded with #IfNotTable, so this is safe to repeat and
    # safe to run before the Install button in Manage Modules.
    PHP_SNIPPET='$_GET["site"] = getenv("LOGICOY_SITE");
        $_SERVER["HTTP_HOST"] = "localhost";
        $ignoreAuth = true;
        require_once "interface/globals.php";
        require_once getenv("LOGICOY_MODULE") . "/ModuleManagerListener.php";
        $listener = ModuleManagerListener::initListenerSelf();
        echo $listener->moduleManagerAction("install", 0, "Success"), PHP_EOL;'

    RUN_AS=""
    if [ "$(id -u 2>/dev/null || echo 1)" -eq 0 ] && [ -n "$WEB_USER" ] && [ "$WEB_USER" != "root" ]; then
        # OpenEMR refuses to run its CLI entry points as root, and files created
        # as root would be unreadable to the web server anyway.
        RUN_AS="$WEB_USER"
    fi

    if [ -n "$RUN_AS" ]; then
        RESULT=$(su -s /bin/sh "$RUN_AS" -c \
            "cd '$OPENEMR_ROOT' && LOGICOY_SITE='$SITE' LOGICOY_MODULE='$TARGET' php -r '$PHP_SNIPPET'" 2>&1) || true
    else
        RESULT=$(cd "$OPENEMR_ROOT" && LOGICOY_SITE="$SITE" LOGICOY_MODULE="$TARGET" php -r "$PHP_SNIPPET" 2>&1) || true
    fi

    if printf '%s' "$RESULT" | grep -q 'Success'; then
        say "module tables created (or already present)"
    else
        # Truncated deliberately: the usual cause is a database that this shell
        # cannot reach, and fifteen lines of ADOdb stack trace reads like a
        # broken install when the files are in fact fine.
        warn "creating the tables did not report success. First lines of the error:"
        printf '%s\n' "$RESULT" | head -4 | sed 's/^/    /' >&2
        warn "the module files are installed correctly — use the Install button in"
        warn "Modules -> Manage Modules to create the tables instead."
    fi
fi

# ----------------------------------------------------------- next steps -----

step "Done — remaining steps are in the OpenEMR interface"

cat <<TXT

  1. Modules -> Manage Modules
     Register  the LogiCoy eRx entry in the unregistered list
     Install   creates the module tables
     Enable

  2. Administration -> Globals -> LogiCoy eRx
     Turn the module on and set the backend base URL supplied by LogiCoy.

  3. Modules -> Manage Modules -> LogiCoy eRx -> config icon
     Load the practice credential. Upload the .pem — do not reference a path
     on a Docker install, it will not survive a container rebuild.

  4. Administration -> Users -> each prescriber
     Fill in the LogiCoy eRx block, then register the prescriber.

  Nothing to schedule: enabling the module adds an OpenEMR background service
  that sends queued prescriptions and collects pharmacy messages every five
  minutes while anyone is signed in to OpenEMR.

  Full instructions, including EPCS setup: $TARGET/docs/INSTALL.md

TXT

exit 0

